     1	import { useEffect, useState } from "react";
     2	import { useTranslation } from "react-i18next";
     3	import { toast } from "sonner";
     4	import { Search } from "lucide-react";
     5	import {
     6	  Dialog,
     7	  DialogContent,
     8	  DialogDescription,
     9	  DialogHeader,
    10	  DialogTitle,
    11	} from "@/components/ui/dialog";
    12	import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
    13	import { Input } from "@/components/ui/input";
    14	import { Textarea } from "@/components/ui/textarea";
    15	import { Button } from "@/components/ui/button";
    16	import { useMemberStore } from "@/hooks/useMemberStore";
    17	import { useIdentityLinkStore } from "@/hooks/useIdentityLinkStore";
    18	import { Member, MemberSearchHitDB } from "@/types/member";
    19	
    20	type Props = {
    21	  open: boolean;
    22	  onOpenChange: (open: boolean) => void;
    23	  workspaceId: string;
    24	  member: Member;
    25	};
    26	
    27	/** Propose an identity link, either by finding the exact target member in a
    28	 *  workspace the caller can already read (search) or, when they can't,
    29	 *  by inviting the target owner to pick their own member (#1014). */
    30	export const ProposeIdentityLinkDialog = ({
    31	  open,
    32	  onOpenChange,
    33	  workspaceId,
    34	  member,
    35	}: Props) => {
    36	  const { t } = useTranslation(undefined, {
    37	    keyPrefix: "sheet.identity-links.propose-dialog",
    38	  });
    39	  const searchOtherTrees = useMemberStore((s) => s.searchOtherTrees);
    40	  const propose = useIdentityLinkStore((s) => s.propose);
    41	  const proposeClaim = useIdentityLinkStore((s) => s.proposeClaim);
    42	
    43	  const [tab, setTab] = useState("search");
    44	  const [query, setQuery] = useState("");
    45	  const [results, setResults] = useState<MemberSearchHitDB[]>([]);
    46	  const [searching, setSearching] = useState(false);
    47	  const [submitting, setSubmitting] = useState(false);
    48	  const [username, setUsername] = useState("");
    49	  const [note, setNote] = useState("");
    50	
    51	  useEffect(() => {
    52	    if (!open) {
    53	      setQuery("");
    54	      setResults([]);
    55	      setUsername("");
    56	      setNote("");
    57	      setTab("search");
    58	    }
    59	  }, [open]);
    60	
    61	  useEffect(() => {
    62	    const term = query.trim();
    63	    if (!term) {
    64	      setResults([]);
    65	      return;
    66	    }
    67	    setSearching(true);
    68	    const handle = setTimeout(() => {
    69	      void searchOtherTrees(term, workspaceId)
    70	        .then(setResults)
    71	        .finally(() => setSearching(false));
    72	    }, 300);
    73	    return () => clearTimeout(handle);
    74	  }, [query, workspaceId, searchOtherTrees]);
    75	
    76	  const handlePick = async (hit: MemberSearchHitDB) => {
    77	    setSubmitting(true);
    78	    try {
    79	      await propose(workspaceId, member.id, hit.workspaceId, hit.id);
    80	      toast.success(t("propose-success"));
    81	      onOpenChange(false);
    82	    } catch (err) {
    83	      console.error(err);
    84	      toast.error(t("propose-error"));
    85	    } finally {
    86	      setSubmitting(false);
    87	    }
    88	  };
    89	
    90	  const handleInvite = async () => {
    91	    if (!username.trim()) return;
    92	    setSubmitting(true);
    93	    try {
    94	      await proposeClaim(
    95	        workspaceId,
    96	        member.id,
    97	        username.trim(),
    98	        note.trim() || undefined,
    99	      );
   100	      toast.success(t("invite-success"));
   101	      onOpenChange(false);
   102	    } catch (err) {
   103	      console.error(err);
   104	      toast.error(t("invite-error"));
   105	    } finally {
   106	      setSubmitting(false);
   107	    }
   108	  };
   109	
   110	  return (
   111	    <Dialog open={open} onOpenChange={onOpenChange}>
   112	      <DialogContent>
   113	        <DialogHeader>
   114	          <DialogTitle>
   115	            {t("title", {
   116	              name: `${member.firstName} ${member.lastName}`.trim(),
   117	            })}
   118	          </DialogTitle>
   119	          <DialogDescription>{t("description")}</DialogDescription>
   120	        </DialogHeader>
   121	        <Tabs value={tab} onValueChange={setTab}>
   122	          <TabsList>
   123	            <TabsTrigger value="search">{t("tab-search")}</TabsTrigger>
   124	            <TabsTrigger value="invite">{t("tab-invite")}</TabsTrigger>
   125	          </TabsList>
   126	
   127	          <TabsContent value="search" className="space-y-3">
   128	            <div className="relative">
   129	              <Search className="absolute left-2 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
   130	              <Input
   131	                className="pl-8"
   132	                placeholder={t("search-placeholder")}
   133	                value={query}
   134	                onChange={(e) => setQuery(e.target.value)}
   135	              />
   136	            </div>
   137	            <div className="max-h-64 space-y-1 overflow-y-auto">
   138	              {query.trim() && !searching && results.length === 0 && (
   139	                <p className="text-sm text-muted-foreground">
   140	                  {t("no-results")}
   141	                </p>
   142	              )}
   143	              {results.map((hit) => (
   144	                <button
   145	                  key={`${hit.workspaceId}:${hit.id}`}
   146	                  type="button"
   147	                  disabled={submitting}
   148	                  className="w-full rounded-md border px-3 py-2 text-left transition-colors hover:bg-accent disabled:opacity-50"
   149	                  onClick={() => void handlePick(hit)}
   150	                >
   151	                  <div className="text-sm font-medium">
   152	                    {hit.firstName} {hit.lastName}
   153	                  </div>
   154	                  <div className="text-xs text-muted-foreground">
   155	                    {hit.workspaceName}
   156	                  </div>
   157	                </button>
   158	              ))}
   159	            </div>
   160	          </TabsContent>
   161	
   162	          <TabsContent value="invite" className="space-y-3">
   163	            <p className="text-sm text-muted-foreground">
   164	              {t("invite-description")}
   165	            </p>
   166	            <Input
   167	              placeholder={t("username-placeholder")}
   168	              value={username}
   169	              onChange={(e) => setUsername(e.target.value)}
   170	            />
   171	            <Textarea
   172	              placeholder={t("note-placeholder")}
   173	              value={note}
   174	              onChange={(e) => setNote(e.target.value)}
   175	              maxLength={500}
   176	            />
   177	            <Button
   178	              className="w-full"
   179	              disabled={submitting || !username.trim()}
   180	              onClick={() => void handleInvite()}
   181	            >
   182	              {t("invite-submit")}
   183	            </Button>
   184	          </TabsContent>
   185	        </Tabs>
   186	      </DialogContent>
   187	    </Dialog>
   188	  );
   189	};

