     1	import { useEffect, useState } from "react";
     2	import { useTranslation } from "react-i18next";
     3	import { toast } from "sonner";
     4	import { Link2, ShieldQuestion } from "lucide-react";
     5	import { Button } from "@/components/ui/button";
     6	import { Badge } from "@/components/ui/badge";
     7	import {
     8	  Item,
     9	  ItemContent,
    10	  ItemDescription,
    11	  ItemTitle,
    12	} from "@/components/ui/item";
    13	import { ConfirmDeleteDialog } from "@/components/shared/dialog/ConfirmDeleteDialog";
    14	import { useIdentityLinkStore } from "@/hooks/useIdentityLinkStore";
    15	import { useWorkspaceStore } from "@/hooks/useWorkspaceStore";
    16	import { useMemberSheetStore } from "@/hooks/useMemberSheetStore";
    17	import { Member } from "@/types/member";
    18	import { IdentityLink, IdentityLinkClaim } from "@/types/identityLink";
    19	import { ProposeIdentityLinkDialog } from "./ProposeIdentityLinkDialog";
    20	
    21	type Props = { member: Member };
    22	
    23	// Stable references so the zustand selectors below don't return a fresh
    24	// array on every render when there's nothing cached yet (which would defeat
    25	// useSyncExternalStore's identity check and re-render in a loop).
    26	const EMPTY_LINKS: IdentityLink[] = [];
    27	const EMPTY_CLAIMS: IdentityLinkClaim[] = [];
    28	
    29	/** Verified/pending cross-workspace identity links plus outgoing claims for
    30	 *  one member (#1014). See app.services.identity_links / identity_link_claims. */
    31	export const IdentityLinksPanel = ({ member }: Props) => {
    32	  const { t } = useTranslation(undefined, {
    33	    keyPrefix: "sheet.identity-links",
    34	  });
    35	  const workspaceId = useWorkspaceStore((s) => s.selectedTree?.id);
    36	  const role = useWorkspaceStore((s) => s.selectedTree?.role);
    37	  const isOwner = role === "owner";
    38	  const canPropose = role === "owner" || role === "editor";
    39	
    40	  const links = useIdentityLinkStore(
    41	    (s) => s.linksByMember[member.id] ?? EMPTY_LINKS,
    42	  );
    43	  const claims = useIdentityLinkStore(
    44	    (s) => s.claimsByMember[member.id] ?? EMPTY_CLAIMS,
    45	  );
    46	  const loadForMember = useIdentityLinkStore((s) => s.loadForMember);
    47	  const approve = useIdentityLinkStore((s) => s.approve);
    48	  const reject = useIdentityLinkStore((s) => s.reject);
    49	  const revoke = useIdentityLinkStore((s) => s.revoke);
    50	  const cancelClaim = useIdentityLinkStore((s) => s.cancelClaim);
    51	
    52	  const [proposeOpen, setProposeOpen] = useState(false);
    53	  const [toRevoke, setToRevoke] = useState<IdentityLink | null>(null);
    54	  const [toReject, setToReject] = useState<IdentityLink | null>(null);
    55	
    56	  useEffect(() => {
    57	    if (!workspaceId) return;
    58	    void loadForMember(workspaceId, member.id);
    59	  }, [workspaceId, member.id, loadForMember]);
    60	
    61	  if (!workspaceId) return null;
    62	
    63	  const run = async (action: () => Promise<void>) => {
    64	    try {
    65	      await action();
    66	    } catch (err) {
    67	      console.error(err);
    68	      toast.error(t("action-error"));
    69	    }
    70	  };
    71	
    72	  const goToCounterpart = (link: IdentityLink) =>
    73	    run(async () => {
    74	      if (!link.counterpart) return;
    75	      await useWorkspaceStore
    76	        .getState()
    77	        .openTreeById(link.counterpart.workspace_id);
    78	      useMemberSheetStore
    79	        .getState()
    80	        .setOpenSheet(link.counterpart.workspace_id, {
    81	          memberId: link.counterpart.member_id,
    82	          tab: "identity",
    83	          mode: "view",
    84	        });
    85	    });
    86	
    87	  const verified = links.filter((l) => l.status === "verified");
    88	  const pending = links.filter((l) => l.status === "proposed");
    89	  const pendingClaims = claims.filter((c) => c.status === "pending");
    90	  const isEmpty =
    91	    verified.length === 0 && pending.length === 0 && pendingClaims.length === 0;
    92	
    93	  return (
    94	    <div className="space-y-3">
    95	      <div className="flex items-center justify-between">
    96	        <h3 className="text-sm font-semibold text-muted-foreground">
    97	          {t("title")}
    98	        </h3>
    99	        {canPropose && (
   100	          <Button
   101	            variant="outline"
   102	            size="sm"
   103	            onClick={() => setProposeOpen(true)}
   104	          >
   105	            <Link2 className="h-4 w-4" />
   106	            {t("propose")}
   107	          </Button>
   108	        )}
   109	      </div>
   110	
   111	      {isEmpty ? (
   112	        <p className="text-sm text-muted-foreground">{t("none")}</p>
   113	      ) : (
   114	        <div className="space-y-2">
   115	          {verified.map((link) => (
   116	            <Item key={link.id} variant="muted">
   117	              <ItemContent>
   118	                <ItemTitle className="flex items-center gap-1.5">
   119	                  {link.counterpart_protected ? (
   120	                    <>
   121	                      <ShieldQuestion className="h-3.5 w-3.5 text-muted-foreground" />
   122	                      {t("protected-counterpart")}
   123	                    </>
   124	                  ) : (
   125	                    (link.counterpart?.display_name ?? t("unnamed-member"))
   126	                  )}
   127	                </ItemTitle>
   128	                <ItemDescription className="flex flex-wrap items-center gap-2">
   129	                  {!link.counterpart_protected && link.counterpart && (
   130	                    <span>{link.counterpart.workspace_name}</span>
   131	                  )}
   132	                  {link.verification_basis === "legacy_dual_write_access" && (
   133	                    <Badge variant="secondary">{t("basis-legacy")}</Badge>
   134	                  )}
   135	                  {!link.counterpart_protected && (
   136	                    <Button
   137	                      variant="link"
   138	                      size="sm"
   139	                      className="h-auto p-0"
   140	                      onClick={() => void goToCounterpart(link)}
   141	                    >
   142	                      {t("go-to-member")}
   143	                    </Button>
   144	                  )}
   145	                  {isOwner && (
   146	                    <Button
   147	                      variant="link"
   148	                      size="sm"
   149	                      className="h-auto p-0 text-destructive"
   150	                      onClick={() => setToRevoke(link)}
   151	                    >
   152	                      {t("revoke")}
   153	                    </Button>
   154	                  )}
   155	                </ItemDescription>
   156	              </ItemContent>
   157	            </Item>
   158	          ))}
   159	
   160	          {pending.map((link) => (
   161	            <Item key={link.id} variant="muted">
   162	              <ItemContent>
   163	                <ItemTitle>
   164	                  {link.counterpart_protected
   165	                    ? t("protected-counterpart")
   166	                    : (link.counterpart?.display_name ?? t("unnamed-member"))}
   167	                </ItemTitle>
   168	                <ItemDescription className="flex flex-wrap items-center gap-2">
   169	                  <Badge variant="outline">{t("status-pending")}</Badge>
   170	                  {isOwner && (
   171	                    <>
   172	                      <Button
   173	                        variant="link"
   174	                        size="sm"
   175	                        className="h-auto p-0"
   176	                        onClick={() =>
   177	                          void run(() =>
   178	                            approve(workspaceId, member.id, link.id),
   179	                          )
   180	                        }
   181	                      >
   182	                        {t("approve")}
   183	                      </Button>
   184	                      <Button
   185	                        variant="link"
   186	                        size="sm"
   187	                        className="h-auto p-0 text-destructive"
   188	                        onClick={() => setToReject(link)}
   189	                      >
   190	                        {t("reject-or-cancel")}
   191	                      </Button>
   192	                    </>
   193	                  )}
   194	                </ItemDescription>
   195	              </ItemContent>
   196	            </Item>
   197	          ))}
   198	
   199	          {pendingClaims.map((claim) => (
   200	            <Item key={claim.id} variant="muted">
   201	              <ItemContent>
   202	                <ItemTitle>
   203	                  {t("claim-to", { username: claim.target_username })}
   204	                </ItemTitle>
   205	                <ItemDescription className="flex flex-wrap items-center gap-2">
   206	                  <Badge variant="outline">{t("status-invited")}</Badge>
   207	                  {canPropose && (
   208	                    <Button
   209	                      variant="link"
   210	                      size="sm"
   211	                      className="h-auto p-0 text-destructive"
   212	                      onClick={() =>
   213	                        void run(() =>
   214	                          cancelClaim(workspaceId, member.id, claim.id),
   215	                        )
   216	                      }
   217	                    >
   218	                      {t("reject-or-cancel")}
   219	                    </Button>
   220	                  )}
   221	                </ItemDescription>
   222	              </ItemContent>
   223	            </Item>
   224	          ))}
   225	        </div>
   226	      )}
   227	
   228	      <ProposeIdentityLinkDialog
   229	        open={proposeOpen}
   230	        onOpenChange={setProposeOpen}
   231	        workspaceId={workspaceId}
   232	        member={member}
   233	      />
   234	
   235	      <ConfirmDeleteDialog
   236	        open={toRevoke !== null}
   237	        onOpenChange={(open) => !open && setToRevoke(null)}
   238	        onConfirm={() => {
   239	          if (toRevoke)
   240	            void run(() => revoke(workspaceId, member.id, toRevoke.id));
   241	          setToRevoke(null);
   242	        }}
   243	        title={t("confirm-revoke-title")}
   244	        description={t("confirm-revoke-description")}
   245	        cancelText={t("confirm-cancel")}
   246	        confirmText={t("revoke")}
   247	      />
   248	
   249	      <ConfirmDeleteDialog
   250	        open={toReject !== null}
   251	        onOpenChange={(open) => !open && setToReject(null)}
   252	        onConfirm={() => {
   253	          if (toReject)
   254	            void run(() => reject(workspaceId, member.id, toReject.id));
   255	          setToReject(null);
   256	        }}
   257	        title={t("confirm-reject-title")}
   258	        description={t("confirm-reject-description")}
   259	        cancelText={t("confirm-cancel")}
   260	        confirmText={t("reject-or-cancel")}
   261	      />
   262	    </div>
   263	  );
   264	};

