     1	import { useEffect, useState } from "react";
     2	import { useTranslation } from "react-i18next";
     3	import { toast } from "sonner";
     4	import { Check, Link2, X } from "lucide-react";
     5	import { ViewLayout } from "@/components/layout/ViewLayout";
     6	import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
     7	import { Button } from "@/components/ui/button";
     8	import { Badge } from "@/components/ui/badge";
     9	import { Card } from "@/components/ui/card";
    10	import {
    11	  Empty,
    12	  EmptyDescription,
    13	  EmptyHeader,
    14	  EmptyMedia,
    15	  EmptyTitle,
    16	} from "@/components/ui/empty";
    17	import { ConfirmDeleteDialog } from "@/components/shared/dialog/ConfirmDeleteDialog";
    18	import { useIdentityLinkStore } from "@/hooks/useIdentityLinkStore";
    19	import { useWorkspaceStore } from "@/hooks/useWorkspaceStore";
    20	import { IdentityLinkClaim } from "@/types/identityLink";
    21	import { CompleteIdentityLinkClaimDialog } from "./CompleteIdentityLinkClaimDialog";
    22	
    23	export const IdentityLinksView = () => {
    24	  const { t } = useTranslation(undefined, { keyPrefix: "identity-links-view" });
    25	  const selectedTree = useWorkspaceStore((s) => s.selectedTree);
    26	  const isOwner = selectedTree?.role === "owner";
    27	
    28	  const workspaceLinks = useIdentityLinkStore((s) => s.workspaceLinks);
    29	  const incomingClaims = useIdentityLinkStore((s) => s.incomingClaims);
    30	  const outgoingClaims = useIdentityLinkStore((s) => s.outgoingClaims);
    31	  const loadWorkspaceLinks = useIdentityLinkStore((s) => s.loadWorkspaceLinks);
    32	  const loadClaimInbox = useIdentityLinkStore((s) => s.loadClaimInbox);
    33	  const approveWorkspaceLink = useIdentityLinkStore(
    34	    (s) => s.approveWorkspaceLink,
    35	  );
    36	  const rejectWorkspaceLink = useIdentityLinkStore(
    37	    (s) => s.rejectWorkspaceLink,
    38	  );
    39	  const revokeWorkspaceLink = useIdentityLinkStore(
    40	    (s) => s.revokeWorkspaceLink,
    41	  );
    42	  const declineClaim = useIdentityLinkStore((s) => s.declineClaim);
    43	  const cancelOutgoingClaim = useIdentityLinkStore(
    44	    (s) => s.cancelOutgoingClaim,
    45	  );
    46	
    47	  const [tab, setTab] = useState("links");
    48	  const [toComplete, setToComplete] = useState<IdentityLinkClaim | null>(null);
    49	  const [toDecline, setToDecline] = useState<IdentityLinkClaim | null>(null);
    50	
    51	  useEffect(() => {
    52	    void loadClaimInbox();
    53	  }, [loadClaimInbox]);
    54	
    55	  useEffect(() => {
    56	    if (selectedTree && isOwner) void loadWorkspaceLinks(selectedTree.id);
    57	  }, [selectedTree, isOwner, loadWorkspaceLinks]);
    58	
    59	  const run = async (
    60	    action: () => Promise<void>,
    61	    errorKey = "action-error",
    62	  ) => {
    63	    try {
    64	      await action();
    65	    } catch (err) {
    66	      console.error(err);
    67	      toast.error(t(errorKey));
    68	    }
    69	  };
    70	
    71	  const pending = workspaceLinks.filter((l) => l.status === "proposed");
    72	  const verified = workspaceLinks.filter((l) => l.status === "verified");
    73	
    74	  return (
    75	    <ViewLayout title={t("title")}>
    76	      <Tabs
    77	        value={tab}
    78	        onValueChange={setTab}
    79	        className="flex h-full min-h-0 flex-1 flex-col"
    80	      >
    81	        <TabsList>
    82	          <TabsTrigger value="links">
    83	            {t("tab-links")}
    84	            {pending.length > 0 && (
    85	              <Badge variant="default" className="ml-1.5 px-1.5">
    86	                {pending.length}
    87	              </Badge>
    88	            )}
    89	          </TabsTrigger>
    90	          <TabsTrigger value="claims">
    91	            {t("tab-claims")}
    92	            {incomingClaims.length > 0 && (
    93	              <Badge variant="default" className="ml-1.5 px-1.5">
    94	                {incomingClaims.length}
    95	              </Badge>
    96	            )}
    97	          </TabsTrigger>
    98	        </TabsList>
    99	
   100	        <TabsContent value="links" className="mt-4 flex-1 space-y-6">
   101	          {!selectedTree ? (
   102	            <p className="text-sm text-muted-foreground">
   103	              {t("no-tree-selected")}
   104	            </p>
   105	          ) : !isOwner ? (
   106	            <p className="text-sm text-muted-foreground">{t("owner-only")}</p>
   107	          ) : (
   108	            <>
   109	              <section className="space-y-3">
   110	                <h2 className="text-sm font-semibold text-muted-foreground">
   111	                  {t("pending-links")}
   112	                </h2>
   113	                {pending.length === 0 ? (
   114	                  <p className="text-sm text-muted-foreground">
   115	                    {t("no-pending-links")}
   116	                  </p>
   117	                ) : (
   118	                  <div className="space-y-2">
   119	                    {pending.map((link) => (
   120	                      <Card
   121	                        key={link.id}
   122	                        className="flex-row items-center gap-3 p-3"
   123	                      >
   124	                        <div className="min-w-0 flex-1">
   125	                          <p className="truncate text-sm font-medium">
   126	                            {link.self.display_name ?? t("unnamed-member")}
   127	                          </p>
   128	                          <p className="truncate text-xs text-muted-foreground">
   129	                            {link.counterpart_protected
   130	                              ? t("protected-counterpart")
   131	                              : `${link.counterpart?.display_name ?? t("unnamed-member")} · ${link.counterpart?.workspace_name ?? ""}`}
